const PaymentMethodSchema = z
  .object({
    type: z
      .string()
      .openapi({
        description:
          'Type of payment method. The following types of the payment method are supported:\n\n* `PayPalEC` - PayPal Express Checkout payment method. Use this type if you are using a [PayPal Payflow Pro Gateway](https://knowledgecenter.zuora.com/CB_Billing/M_Payment_Gateways/Supported_Payment_Gateways/PayPal_Payflow_Pro%2C_Website_Payments_Payflow_Edition%2C_Website_Pro_Payment_Gateway) instance.\n* `PayPalNativeEC` - PayPal Native Express Checkout payment method. Use this type if you are using a [PayPal Express Checkout Gateway](https://knowledgecenter.zuora.com/CB_Billing/M_Payment_Gateways/Supported_Payment_Gateways/PayPal_Express_Checkout_Gateway) instance.\n* `PayPalAdaptive` - PayPal Adaptive payment method. Use this type if you are using a [PayPal Adaptive Payment Gateway](https://knowledgecenter.zuora.com/CB_Billing/M_Payment_Gateways/Supported_Payment_Gateways/PayPal_Adaptive_Payments_Gateway) instance.\n* `CreditCard` - Credit card payment method.\n* `ACH` - ACH payment method.\n* `SEPA` - Single Euro Payments Area.\n* `Betalingsservice` - Direct Debit DK.\n* `Autogiro` - Direct Debit SE.\n* `Bacs` - Direct Debit UK.\n* You can also specify a custom payment method type. This type is only available if the Universal Payment Connector and Open Payment Method services are enabled. See [Set up custom payment gateways and payment methods](https://knowledgecenter.zuora.com/Billing/Billing_and_Payments/MB_Set_up_custom_payment_gateways_and_payment_methods) for details.\n',
      }),
  })
  .openapi({ required: ['type'] })
  .and(CreatePMPayPalECPayPalNativeECSchema)
  .and(CreatePaymentMethodPayPalAdaptiveSchema)
  .and(CreatePaymentMethodCreditCardSchema)
  .and(CreatePaymentMethodACHSchema)
  .and(CreatePaymentMethodCommonSchema)
  .and(PaymentMethodObjectCustomFieldsSchema)
  .and(CreatePaymentMethodBankTransferSchema)
  .openapi({
    description:
      'Payment method to create for this new account. Supports all the payment methods that are supported in the "Create payment method" operation. See for more information about how to use this field in [Create payment method](https://www.zuora.com/developer/api-reference/#operation/POST_PaymentMethods).\n',
  })
  .openapi('PaymentMethod')

