const AmendmentSchema = z
  .object({
    AutoRenew: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          ' Determines whether the subscription is automatically renewed, or whether it expires at the end of the term and needs to be manually renewed. For amendment of type `TermsAndConditions`, this field is only required if you change the automatic renewal status of a subscription.\n\n\n**Values**: true, false ',
      }),
    Code: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' A unique alphanumeric string that identifies the amendment.\n\n\n**Character limit**: 50\n\n**Values**: automatically generated\n',
      }),
    ContractEffectiveDate: z.iso
      .date()
      .openapi({
        description:
          " The date when the amendment's changes become effective for billing purposes.\n",
      }),
    CreatedById: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The user ID of the person who created the amendment.\n\n\n**Character limit**: 32\n\n**Values**: automatically generated ',
      }),
    CreatedDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          ' The date when the amendment was created.\n\n\n**Values**: automatically generated ',
      }),
    CurrentTerm: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          ' The length of the period for the current subscription term. This field can be updated when Status is `Draft`.\n\nThis field is only required if the `Type` field is set to `TermsAndConditions` and `TermType` is set to `TERMED`. This field is not required if `TermType` is set to `EVERGREEN`.\n\n\n**Values**: a valid number ',
      }),
    CurrentTermPeriodType: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The period type for the current subscription term. This field is only required if the `Type` field is set to `TermsAndConditions` and `TermType` is set to `TERMED`. This field is not required if `TermType` is set to `EVERGREEN`.\n\n**Values**:\n\n- `Month` (default)\n- `Year`\n- `Day`\n- `Week`\n\n\n**Note**:\n\n- This field can be updated when Status is `Draft`.\n- This field is used with the CurrentTerm field to specify the current subscription term.\n',
      }),
    CustomerAcceptanceDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          "The date when the customer accepts the amendment's changes to the subscription.\n\nThis field is only required if [Zuora is configured to require customer acceptance in Z-Billing](https://knowledgecenter.zuora.com/CB_Billing/W_Billing_and_Payments_Settings/Define_Default_Subscription_Settings) and the subscription is currently in the Pending Acceptance status (the value of the `Status` field is currently `PendingAcceptance`).\n\nUse this field together with the `Status` field. When you set a date in this field as a customer acceptance date, you should also set the `Status` field as `Completed`.\n",
      }),
    Description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' A description of the amendment.\n\n\n**Character limit**: 500\n\n**Values**: maximum 500 characters ',
      }),
    DestinationAccountId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The ID of the subscription owner that the subscription is being transferred to.\n\n\n**Character limit**: 32\n\n**Values**: a valid account ID ',
      }),
    DestinationInvoiceOwnerId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The ID of the invoice owner that the subscription is being transferred to.\n\n\n**Character limit**: 32\n\n**Values**: a valid invoice ID ',
      }),
    EffectiveDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          " The date when the amendment's changes take effective. This field validates that the amendment's changes are within valid ranges of products and product rate plans.\nThis field is only required if the `Type` field is set to `Cancellation`.\n\n",
      }),
    Name: z
      .string()
      .openapi({
        description:
          ' The name of the amendment.\n\n\n**Character limit**: 100\n\n**Values**: a string of 100 characters or fewer ',
      }),
    RatePlanData: z
      .object({
        RatePlan: RatePlanSchema,
        RatePlanChargeData: z
          .array(RatePlanChargeDataInRatePlanDataSchema)
          .exactOptional()
          .openapi({ description: '' }),
        SubscriptionProductFeatureList: SubscriptionProductFeatureListSchema.exactOptional(),
      })
      .exactOptional()
      .openapi({
        description:
          'A container for one `RatePlanData`. This field is only required if the `Type` field is set to `NewProduct`, `RemoveProduct`, or `UpdateProduct`.\n',
        required: ['RatePlan'],
      }),
    RenewalSetting: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' Specifies whether a termed subscription will remain termed or change to evergreen when it is renewed.\n\nThis field is only required if the `TermType` field is set to `Termed`.\n\n\n**Values**: RENEW_WITH_SPECIFIC_TERM (default), RENEW_TO_EVERGREEN ',
      }),
    RenewalTerm: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          ' The term of renewal for the amended subscription. This field can be updated when Status is `Draft`.\nThis field is only required if the `Type` field is set to `TermsAndConditions`.\n\n\n**Values:** a valid number ',
      }),
    RenewalTermPeriodType: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The period type for the subscription renewal term. This field can be updated when Status is `Draft`.\n**Required**: Only if the value of the Type field is set to `TermsAndConditions`. This field is used with the RenewalTerm field to specify the subscription renewal term.\n\n\n**Values**:\n\n- `Month` (default)\n- `Year`\n- `Day`\n- `Week`\n',
      }),
    ResumeDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'The date when the subscription resumption takes effect. See [Resume Date](https://knowledgecenter.zuora.com/BC_Subscription_Management/Subscriptions/Resume_a_Subscription#Resume_Date) for more information.\n\nThis field is only required if you resume a suspended subscription.\n',
      }),
    ServiceActivationDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'The date when service is activated.\n\nThis field is only required if [Zuora is configured to require service activation in Z-Billing](https://knowledgecenter.zuora.com/CB_Billing/W_Billing_and_Payments_Settings/Define_Default_Subscription_Settings) and the subscription is currently in the Pending Activation status (the value of the `Status` field is currently `PendingActivation`).\n\nUse this field together with the `Status` field. When you set a date in this field as a service activation date, you should also set the `Status` field as the expected next phase status: `Completed` or `PendingAcceptance`.\n',
      }),
    SpecificUpdateDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'The date when the UpdateProduct amendment takes effect. This field is only applicable if there is already a future-dated UpdateProduct amendment on the subscription.\n\n\nFor the UpdateProduct amendments, this field is only required if there is already a future-dated UpdateProduct amendment on the subscription.\n',
      }),
    Status: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The status of the amendment. Type: string (enum)\n\n\n\n**Values**: one of the following:\n\n- Draft (default, if left null)\n- Pending Activation\n- Pending Acceptance\n- Completed\n',
      }),
    SubscriptionId: z
      .string()
      .openapi({
        description:
          ' The ID of the subscription that the amendment changes.\n\n\n**Character limit**: 32\n\n**Values**: a valid subscription ID ',
      }),
    SuspendDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'The date when the subscription suspension takes effect. See [Suspend Date](https://knowledgecenter.zuora.com/BC_Subscription_Management/Subscriptions/Suspend_a_Subscription#Suspend_Date) for more information.\n\nThis field is only required if you suspend an active subscription.\n',
      }),
    TermStartDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          ' The date when the new terms and conditions take effect.\nThis field is only required if the `Type` field is set to `TermsAndConditions`.\n',
      }),
    TermType: z
      .string()
      .exactOptional()
      .openapi({
        description:
          " Indicates if the subscription isTERMED or EVERGREEN.\n\n- A TERMED subscription has an expiration date, and must be manually renewed.\n- An EVERGREEN subscription doesn't have an expiration date, and must be manually ended.\n\nWhen as part of an amendment of type `TermsAndConditions`, this field is required to change the term type of a subscription.\n\n\n**Character limit**: 9\n\n**Values**: TERMED, EVERGREEN ",
      }),
    Type: z
      .string()
      .openapi({
        description:
          " The type of amendment.\n\n\n**Character limit**: 18\n\n\n\n**Values**: one of the following:\n\n- Cancellation\n- NewProduct\n- OwnerTransfer (If this value is chosen, the `ContractEffectiveDate`, `ServiceActivationDate`, and `CustomerAcceptanceDate` fields will all be automatically set to today's date, and any values passed from the API are ignored.)\n- RemoveProduct\n- Renewal\n- UpdateProduct\n- TermsAndConditions\n- SuspendSubscription\n- ResumeSubscription\n",
      }),
    UpdatedById: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The ID of the user who last updated the amendment.\n\n\n**Character limit**: 32\n\n**Values**: automatically generated ',
      }),
    UpdatedDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          ' The date when the amendment was last updated.\n\n\n**Values**: automatically generated ',
      }),
  })
  .openapi({ required: ['SubscriptionId', 'Type', 'ContractEffectiveDate', 'Name'] })
  .openapi('Amendment')

const AmendRequestSchema = z
  .object({
    AmendOptions: z
      .object({
        ApplicationOrder: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'The priority order to apply credit memos and/or unapplied payments to an invoice. Possible item values are: `CreditMemo`, `UnappliedPayment`.\n\n**Note:**\n  - This field is only available if you have the Invoice Settlement feature enabled and set the `X-Zuora-WSDL-Version` request header to `107` or later.\n  - This field is valid only if the `applyCredit` field is set to `true`.\n  - If no value is specified for this field, the default priority order is used, ["CreditMemo", "UnappliedPayment"], to apply credit memos first and then apply unapplied payments.\n  - If only one item is specified, only the items of the spedified type are applied to invoices. For example, if the value is `["CreditMemo"]`, only credit memos are used to apply to invoices.\n',
          }),
        ApplyCredit: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Whether to automatically apply credit memos or unapplied payments, or both to an invoice.\n\nIf the value is `true`, the credit memo or unapplied payment, or both will be automatically applied to the invoice. If no value is specified or the value is `false`, no action is taken.\n\n**Note**: This field is only available if you have the Invoice Settlement feature enabled and set the `X-Zuora-WSDL-Version` request header to `107` or later.\n',
          }),
        ApplyCreditBalance: z.boolean().exactOptional().openapi({ description: '' }),
        ElectronicPaymentOptions: ElectronicPaymentOptionsSchema.exactOptional(),
        ExternalPaymentOptions: ExternalPaymentOptionsSchema.exactOptional(),
        GenerateInvoice: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Determines whether to generate an invoice to immediately bill the customer for a new product or changes of Terms And Conditions. As a best practice, set this value to true to prevent any errors that might occur if the account has a balance.\n\n**Note:** \n* Even if you do not include this field in the amend action, Zuora still parses this field with the default value - `true`, when processing the amend action. If you do not want to generate the invoice after creating the New Product or Term And Condition amendment, set the value of this field to `false` in the request.\n* If `EnablePreviewMode=true` is specified in the PreviewOptions container, then preview mode will be enabled and an invoice will not be generated, regardless of whether `GenerateInvoice` is specified as `true` or `false`.\n',
          }),
        InvoiceProcessingOptions: InvoiceProcessingOptionsSchema.exactOptional(),
        ProcessPayments: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Determines whether to collect payment against the invoice generated by the amend() call. \n\n**Note:** \n* Even if you do not include this field in the amend action, Zuora still parses this field with the default value, true, when processing the amend action. If you do not want to collect payment against the generated invoice after creating the New Product or Term And Condition amendment, set the value of this field to `false` in the request. \n* If you have the [Invoice Settlement](https://knowledgecenter.zuora.com/Billing/Billing_and_Payments/Invoice_Settlement) feature enabled, Zuora does not support using this field to collect payments against invoices.\n\nIf a temporary error that Zuora cannot create or submit a payment to the gateway is seen, Zuora will automatically retry the action to collect the payment.\n\nYou can contact [Zuora Global Support](https://support.zuora.com/) to set the maximum number of retries that Zuora can perform. The number can range from 0 to 2 with a default value of 0. However, retrying the request can make the API call take longer than expected. Zuora does not guarantee the retry could be completed within the timeout limit. \n\n**Note**: The retry mechanism does not support the preview mode of the amend() call.\n',
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Use the `AmendOptions` container to specify billing options, such as invoice generation and when to process payments.\n',
        required: [],
      }),
    Amendments: z
      .array(AmendmentSchema)
      .openapi({
        description:
          'The `Amendment` object holds the changes that you want to make to the Subscription specified by the `SubscriptionId`, \nincluding its `RatePlan`, `RatePlanCharge`, and `RatePlanChargeTier`.\n',
      }),
    PreviewOptions: z
      .object({
        EnablePreviewMode: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              ' Determines whether to create an amendment or display a preview of the change.',
          }),
        IncludeExistingDraftInvoiceItems: z
          .boolean()
          .exactOptional()
          .openapi({
            description: ' Specifies whether to include draft invoice items in amendment previews.',
          }),
        NumberOfPeriods: z
          .int32()
          .exactOptional()
          .openapi({
            description: ' Indicates the number of invoice periods to show in a preview.',
          }),
        PreviewThroughTermEnd: z
          .boolean()
          .exactOptional()
          .openapi({
            description: ' Request to preview the charge through the end of the subscription term.',
          }),
        PreviewType: z
          .string()
          .exactOptional()
          .openapi({
            description: ' The type of preview you will receive from a preview request.',
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Use the `PreviewOptions` container to preview an amendment before committing its changes to a subscription. \nYou can use a preview to provide a quote of the new charges to a customer before the customer commits to the amended subscription. \nFor example, make an Amend call with an Amendment object that removes an existing rate plan, \nanother Amendment object that adds a new rate plan, and turn on the preview options.\n',
        required: [],
      }),
  })
  .openapi({ required: ['Amendments'] })
  .openapi('AmendRequest')

const NewChargeMetricsSchema = z
