const PreviewOrderChargeOverrideSchema = z
  .object({
    billing: z
      .object({
        billCycleDay: z
          .int()
          .min(0)
          .max(31)
          .exactOptional()
          .openapi({
            description:
              'Day of the month that each billing period begins on. Only applicable if the value of the `billCycleType` field is `SpecificDayofMonth`.\n',
          }),
        billCycleType: z
          .enum([
            'DefaultFromCustomer',
            'SpecificDayofMonth',
            'SubscriptionStartDay',
            'ChargeTriggerDay',
            'SpecificDayofWeek',
          ])
          .exactOptional()
          .openapi({
            description:
              'Specifies how Zuora determines the day that each billing period begins on.\n\n  * `DefaultFromCustomer` - Each billing period begins on the bill cycle day of the account that owns the subscription.\n  * `SpecificDayofMonth` - Use the `billCycleDay` field to specify the day of the month that each billing period begins on.\n  * `SubscriptionStartDay` - Each billing period begins on the same day of the month as the start date of the subscription.\n  * `ChargeTriggerDay` - Each billing period begins on the same day of the month as the date when the charge becomes active.\n  * `SpecificDayofWeek` - Use the `weeklyBillCycleDay` field to specify the day of the week that each billing period begins on.\n',
          }),
        billingPeriod: z
          .enum([
            'Month',
            'Quarter',
            'Semi_Annual',
            'Annual',
            'Eighteen_Months',
            'Two_Years',
            'Three_Years',
            'Five_Years',
            'Specific_Months',
            'Subscription_Term',
            'Week',
            'Specific_Weeks',
          ])
          .exactOptional()
          .openapi({
            description:
              'Billing frequency of the charge. The value of this field controls the duration of each billing period.\n\nIf the value of this field is `Specific_Months` or `Specific_Weeks`, use the `specificBillingPeriod` field to specify the duration of each billing period.\n',
          }),
        billingPeriodAlignment: z
          .enum(['AlignToCharge', 'AlignToSubscriptionStart', 'AlignToTermStart'])
          .exactOptional()
          .openapi({
            description:
              'Specifies how Zuora determines when to start new billing periods. You can use this field to align the billing periods of different charges.\n\n* `AlignToCharge` - Zuora starts a new billing period on the first billing day that falls on or after the date when the charge becomes active.\n* `AlignToSubscriptionStart` - Zuora starts a new billing period on the first billing day that falls on or after the start date of the subscription.\n* `AlignToTermStart` - For each term of the subscription, Zuora starts a new billing period on the first billing day that falls on or after the start date of the term.\n\nSee the `billCycleType` field for information about how Zuora determines the billing day.\n',
          }),
        billingTiming: z
          .enum(['IN_ADVANCE', 'IN_ARREARS'])
          .exactOptional()
          .openapi({
            description:
              'Specifies whether to invoice for a billing period on the first day of the billing period (billing in advance) or the first day of the next billing period (billing in arrears).\n',
          }),
        specificBillingPeriod: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'Duration of each billing period in months or weeks, depending on the value of the `billingPeriod` field. Only applicable if the value of the `billingPeriod` field is `Specific_Months` or `Specific_Weeks`.\n',
          }),
        weeklyBillCycleDay: z
          .enum(['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'])
          .exactOptional()
          .openapi({
            description:
              'Day of the week that each billing period begins on. Only applicable if the value of the `billCycleType` field is `SpecificDayofWeek`.\n',
          }),
      })
      .exactOptional()
      .openapi({ description: 'Billing information about the charge.\n', required: [] }),
    chargeNumber: z
      .string()
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'Charge number of the charge. For example, C-00000307.\n\nIf you do not set this field, Zuora will generate the charge number.\n',
      }),
    customFields: RatePlanChargeObjectCustomFieldsSchema.exactOptional(),
    description: z
      .string()
      .max(500)
      .exactOptional()
      .openapi({ description: 'Description of the charge.\n' }),
    endDate: EndConditionsSchema.exactOptional(),
    pricing: z
      .object({
        chargeModelData: ChargeModelDataOverrideSchema.exactOptional(),
        discount: DiscountPricingOverrideSchema.exactOptional(),
        oneTimeFlatFee: OneTimeFlatFeePricingOverrideSchema.exactOptional(),
        oneTimePerUnit: OneTimePerUnitPricingOverrideSchema.exactOptional(),
        oneTimeTiered: OneTimeTieredPricingOverrideSchema.exactOptional(),
        oneTimeVolume: OneTimeVolumePricingOverrideSchema.exactOptional(),
        recurringFlatFee: RecurringFlatFeePricingOverrideSchema.exactOptional(),
        recurringPerUnit: RecurringPerUnitPricingOverrideSchema.exactOptional(),
        recurringTiered: RecurringTieredPricingOverrideSchema.exactOptional(),
        recurringVolume: RecurringVolumePricingOverrideSchema.exactOptional(),
        usageFlatFee: UsageFlatFeePricingOverrideSchema.exactOptional(),
        usageOverage: UsageOveragePricingOverrideSchema.exactOptional(),
        usagePerUnit: UsagePerUnitPricingOverrideSchema.exactOptional(),
        usageTiered: UsageTieredPricingOverrideSchema.exactOptional(),
        usageTieredWithOverage: UsageTieredWithOveragePricingOverrideSchema.exactOptional(),
        usageVolume: UsageVolumePricingOverrideSchema.exactOptional(),
      })
      .exactOptional()
      .openapi({ description: 'Pricing information about the charge.\n', required: [] }),
    productRatePlanChargeId: z
      .string()
      .openapi({
        description:
          'Internal identifier of the product rate plan charge that the charge is based on.\n',
      }),
    revRecCode: z
      .string()
      .max(70)
      .exactOptional()
      .openapi({ description: 'Revenue Recognition Code\n' }),
    revRecTriggerCondition: z
      .enum(['Contract Effective Date', 'Service Activation Date', 'Customer Acceptance Date'])
      .exactOptional()
      .openapi({
        description:
          'Specifies the revenue recognition trigger condition.\n\n  * `Contract Effective Date` \n  * `Service Activation Date`\n  * `Customer Acceptance Date`\n',
      }),
    revenueRecognitionRuleName: z
      .enum(['Recognize upon invoicing', 'Recognize daily over time'])
      .exactOptional()
      .openapi({
        description:
          'Specifies the revenue recognition rule.\n\n  * `Recognize upon invoicing` \n  * `Recognize daily over time`\n',
      }),
    startDate: PreviewOrderTriggerParamsSchema.exactOptional(),
    uniqueToken: z
      .string()
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'Unique identifier for the charge. This identifier enables you to refer to the charge before the charge has an internal identifier in Zuora.\n\nFor instance, suppose that you want to use a single order to add a product to a subscription and later update the same product. When you add the product, you can set a unique identifier for the charge. Then when you update the product, you can use the same unique identifier to specify which charge to modify.\n',
      }),
  })
  .openapi({
    description: 'Charge associated with a rate plan.\n',
    required: ['productRatePlanChargeId'],
    title: 'charge',
  })
  .openapi('PreviewOrderChargeOverride')

