const PUTRSTermTypeSchema = z
  .object({
    distributionType: z
      .enum([
        'Daily Distribution',
        'Monthly Distribution (Back Load)',
        'Monthly Distribution (Front Load)',
        'Monthly Distribution (Proration by Days)',
      ])
      .exactOptional()
      .openapi({
        description:
          'How you want to distribute the revenue. \n\n\n* Daily Distribution: Distributes revenue evenly across each day between the recognitionStart and recognitionEnd dates.\n* Monthly Distribution (Back Load): Back loads the revenue so you distribute the monthly amount in the partial month in the end only.\n* Monthly Distribution (Front Load): Front loads the revenue so you distribute the monthly amount in the partial month in the beginning only.\n* Monthly Distribution (Proration by Days): Splits the revenue amount between the two partial months.\n\n**Note:** To use any of the Monthly Distribution options, you must have the "Monthly recognition over time" model enabled in **Settings > Finance > Manage Revenue Recognition Models** in the Zuora UI.\n',
      }),
    eventType: z
      .enum([
        'Invoice Posted',
        'Invoice Item Adjustment Created',
        'Invoice Canceled',
        'Invoice Item Adjustment Canceled',
        'Revenue Distributed',
        'Credit Memo Posted',
        'Debit Memo Posted',
      ])
      .exactOptional()
      .openapi({
        description:
          'Label of the revenue event type. Revenue event type labels can be duplicated. You can configure your revenue event type labels by navigating to **Settings > Finance > Configure Revenue Event Types** in the Zuora UI.\n\nNote that `Credit Memo Posted` and `Debit Memo Posted` are only available if you enable the Invoice Settlement feature.\n',
      }),
    eventTypeSystemId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'System ID of the revenue event type. Each eventType has a unique system ID. You can configure your revenue event type system IDs by navigating to **Settings > Finance > Configure Revenue Event Types** in the Zuora UI.\n',
      }),
    notes: z
      .string()
      .exactOptional()
      .openapi({ description: 'Additional information about this record.\n' }),
    recognitionEnd: z.iso
      .date()
      .openapi({
        description:
          'The end date of a recognition period in `yyyy-mm-dd` format. \n\nThe maximum difference between the `recognitionStart` and `recognitionEnd` date fields is equal to 250 multiplied by the length of an accounting period.\n',
      }),
    recognitionStart: z.iso
      .date()
      .openapi({
        description:
          'The start date of a recognition period in `yyyy-mm-dd` format.\n\nIf there is a closed accounting period between the `recognitionStart` and `recognitionEnd` dates, the revenue that would be placed in the closed accounting period is instead placed in the next open accounting period.\n',
      }),
  })
  .openapi({ required: ['recognitionEnd', 'recognitionStart'] })
  .and(RevenueEventObjectCustomFieldsSchema)
  .openapi({
    example: {
      distributionType: 'Daily distribution',
      eventType: 'Revenue Distributed',
      eventTypeSystemId: 'RevenueDistributed__z',
      notes: 'manual distribute revenue by usage',
      recognitionEnd: '2015-12-31',
      recognitionStart: '2015-12-1',
    },
  })
  .openapi('PUTRSTermType')

