const PostNonRefRefundTypeSchema = z
  .object({
    comment: z
      .string()
      .min(0)
      .max(255)
      .exactOptional()
      .openapi({ description: 'Comments about the refund.\n' }),
    financeInformation: z
      .object({
        bankAccountAccountingCode: z
          .string()
          .min(0)
          .max(100)
          .exactOptional()
          .openapi({
            description:
              'The accounting code that maps to a bank account in your accounting system.\n',
          }),
        onAccountAccountingCode: z
          .string()
          .min(0)
          .max(100)
          .exactOptional()
          .openapi({
            description:
              'The accounting code that maps to an on account in your accounting system.\n',
          }),
        transferredToAccounting: z
          .enum(['Processing', 'Yes', 'No', 'Error', 'Ignore'])
          .exactOptional()
          .openapi({
            description:
              'Whether the refund was transferred to an external accounting system. Use this field for integration with accounting systems, such as NetSuite. \n',
          }),
        unappliedPaymentAccountingCode: z
          .string()
          .min(0)
          .max(100)
          .exactOptional()
          .openapi({ description: 'The accounting code for the unapplied payment.\n' }),
      })
      .exactOptional()
      .openapi({
        description: 'Container for the finance information related to the refund.\n',
        required: [],
      }),
    gatewayId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the gateway instance that processes the refund. This field can be specified only for electronic refunds. The ID must be a valid gateway instance ID, and this gateway must support the specific payment method. \n\nIf no gateway ID is specified, the default gateway in the billing account configuration will be used. If no gateway is specified in the billing account, the default gateway of the corresponding tenant will be used.\n',
      }),
    gatewayOptions: z
      .object({
        key: z
          .string()
          .exactOptional()
          .openapi({ description: 'The name of a gateway-specific parameter.\n' }),
        value: z
          .string()
          .exactOptional()
          .openapi({ description: 'The value of the gateway-specific parameter.\n' }),
      })
      .exactOptional()
      .openapi({
        description: 'The field used to pass gateway-specific parameters and parameter values.\n',
        required: [],
      }),
    items: z
      .array(RefundCreditMemoItemTypeSchema)
      .exactOptional()
      .openapi({
        description:
          'Container for credit memo items. The maximum number of items is 1,000.\n\n**Note:** This field is only available if you have the [Invoice Item Settlement](https://knowledgecenter.zuora.com/Billing/Billing_and_Payments/Invoice_Settlement/C_Invoice_Item_Settlement) feature enabled. Invoice Item Settlement must be used together with other Invoice Settlement features (Unapplied Payments, and Credit and Debit memos).  If you wish to enable Invoice Settlement, see [Invoice Settlement Enablement and Checklist Guide](https://knowledgecenter.zuora.com/Billing/Billing_and_Payments/Invoice_Settlement/Invoice_Settlement_Migration_Checklist_and_Guide) for more information.\n',
      }),
    methodType: z
      .enum([
        'ACH',
        'Cash',
        'Check',
        'CreditCard',
        'PayPal',
        'WireTransfer',
        'DebitCard',
        'CreditCardReferenceTransaction',
        'BankTransfer',
        'Other',
      ])
      .exactOptional()
      .openapi({
        description:
          'How an external refund was issued to a customer. This field is required for an external refund and must be left empty for an electronic refund. You can issue an external refund on a credit memo.\n',
      }),
    paymentMethodId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the payment method used for the refund. This field is required for an electronic refund, and the value must be an electronic payment method ID. This field must be left empty for an external refund. \n',
      }),
    reasonCode: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A code identifying the reason for the transaction. The value must be an existing reason code or empty. If you do not specify a value, Zuora uses the default reason code.\n',
      }),
    referenceId: z
      .string()
      .min(0)
      .max(100)
      .exactOptional()
      .openapi({
        description:
          'The transaction ID returned by the payment gateway for an electronic refund. Use this field to reconcile refunds between your gateway and Zuora Payments.\n',
      }),
    refundDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          'The date when the refund takes effect, in `yyyy-mm-dd` format. The date of the refund cannot be before the credit memo date. Specify this field only for external refunds. Zuora automatically generates this field for electronic refunds.\n',
      }),
    secondRefundReferenceId: z
      .string()
      .min(0)
      .max(100)
      .exactOptional()
      .openapi({
        description:
          'The transaction ID returned by the payment gateway if there is an additional transaction for the refund. Use this field to reconcile payments between your gateway and Zuora Payments.\n',
      }),
    softDescriptor: z
      .string()
      .max(35)
      .exactOptional()
      .openapi({
        description:
          'A payment gateway-specific field that maps to Zuora for the gateways, Orbital, Vantiv and Verifi.',
      }),
    softDescriptorPhone: z
      .string()
      .max(20)
      .exactOptional()
      .openapi({
        description:
          'A payment gateway-specific field that maps to Zuora for the gateways, Orbital, Vantiv and Verifi.',
      }),
    totalAmount: z
      .float64()
      .openapi({
        description:
          'The total amount of the refund. The amount cannot exceed the unapplied amount of the associated credit memo. If the original credit memo was applied to one or more invoices or debit memos, you have to unapply a full or partial credit memo from the invoices or debit memos, and then refund the full or partial unapplied credit memo to your customers.\n',
      }),
    type: z.enum(['External', 'Electronic']).openapi({ description: 'The type of the refund.\n' }),
  })
  .openapi({ required: ['totalAmount', 'type'] })
  .and(RefundObjectNSFieldsSchema)
  .and(RefundObjectCustomFieldsSchema)
  .openapi({
    example: {
      gatewayOptions: { Comments: 'test', IPAddress: '192.168.1.1' },
      methodType: 'CreditCard',
      refundDate: '2017-03-02',
      totalAmount: 7.1,
      type: 'External',
    },
  })
  .openapi('PostNonRefRefundType')

