const ProxyModifyProductRatePlanSchema = z
  .object({
    ActiveCurrencies: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'A list of 3-letter currency codes representing active currencies for the product rate plan. Use a comma to separate each currency code.\n\nIf the request body contains this field, the value of this field must contain the desired list of active currencies. The new list can never have more than four differences from the existing list.\n\nThis field cannot be used to modify the status of more than four currencies in a single request. For example, in a single request, you can only activate four currencies, or deactivate four currencies, or activate two and deactivate two. Making more than four changes to currencies always requires more than one call.\n\nWhen specifying this field in the update request, you must provide the full list of active currencies you want, not just incremental changes. For each active currency update, provide the following currencies in the list:\n\nCurrent active currencies + at most four changes (additions or deletions)\n',
      }),
    Description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A description of the product rate plan. **Character limit**: 500 **Values**: a string of 500 characters or fewer ',
      }),
    EffectiveEndDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          " The date when the product rate plan expires and can't be subscribed to, in `yyyy-mm-dd` format.\n**Character limit**: 29 ",
      }),
    EffectiveStartDate: z.iso
      .date()
      .exactOptional()
      .openapi({
        description:
          ' The date when the product rate plan becomes available and can be subscribed to, in `yyyy-mm-dd` format.\n**Character limit**: 29 ',
      }),
    Name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The name of the product rate plan. The name doesn't have to be unique in a Product Catalog, but the name has to be unique within a product. **Character limit**: 100 **Values**: a string of 100 characters or fewer ",
      }),
    ProductId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the product that contains the product rate plan. **Character limit**: 32 **Values**: a string of 32 characters or fewer ',
      }),
  })
  .openapi({ required: [] })
  .and(ProductRatePlanObjectNSFieldsSchema)
  .and(ProductRatePlanObjectCustomFieldsSchema)
  .openapi({
    example: { Id: '2c93808457d787030157e02da0d91852', Name: 'ProductRatePlan1476934869186_new' },
  })
  .openapi('ProxyModifyProductRatePlan')

