const ProxyModifyUnitOfMeasureSchema = z
  .object({
    Active: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          ' Indicates if the UOM is available for new product rate plans. The default value is `true`.\n**Character limit**: 5 **Values**: `true`, `false ` ',
      }),
    DecimalPlaces: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          "The number of digits to the right of the decimal point that you want to measure for the unit. To use whole numbers only, set this value to 0. You can't change this value after this `UOM` is used in any product, subscription, or usage. **Character limit**: 1 **Values**: an integer between 0 and 9, exclusive ",
      }),
    DisplayedAs: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The name of the UOM that you want displayed on invoices. The default value is the `UomName` field value. **Character limit**: 50 **Values**: A string of 50 characters or fewer ',
      }),
    RoundingMode: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' Specifies whether to round the UOM value up or down when the value exceeds the `DecimalPlaces` field value. The default value is `Up`.\n**Character limit**: 4 **Values**: `Up`, `Down` ',
      }),
    UomName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          ' The name of the UOM, such as license or GB. This name is displayed in query results and in the web-based UI labels. If you want a different name to be displayed on invoices, then use the `DisplayedAs` field to provide the invoice label.\n**Character limit**: 50 **Values**: a string of 50 characters or fewer ',
      }),
  })
  .openapi({ required: [] })
  .openapi('ProxyModifyUnitOfMeasure')

