const SubmitDataQueryRequestSchema = z
  .object({
    columnSeparator: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The column separator. Only applicable if the `outputFormat` is `DSV`.\n',
      }),
    compression: z
      .enum(['NONE', 'GZIP', 'ZIP'])
      .openapi({ description: 'Specifies whether Zuora compresses the query results.\n' }),
    encryptionKey: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Base-64 encoded public key of an RSA key-pair. \n\nNote that Data Query only supports 1024-bit RSA keys.\n\nIf you set this field, Zuora encrypts the query results using the provided public key. You must use the corresponding private key to decrypt the query results.\n',
      }),
    output: z
      .object({ target: z.literal('S3').openapi({ description: 'Set this field to `S3`.\n' }) })
      .openapi({
        description: 'Additional information about the query results.\n',
        required: ['target'],
      }),
    outputFormat: z
      .enum(['JSON', 'CSV', 'TSV', 'DSV'])
      .openapi({
        description:
          'Specifies the format of the query results.\n\n* `JSON` - Each row in the query results will be a JSON object. The format of the query result file is [JSON Lines](http://jsonlines.org/).\n* `CSV` - Each row in the query results will be a comma-separated list of values.\n* `TSV` - Each row in the query results will be a tab-separated list of values.\n* `DSV` - Pass any character as your custom delimiter into the `columnSeparator` field.\n',
      }),
    query: z
      .string()
      .openapi({
        description:
          'The query to perform. See [SQL Queries in Data Query](https://knowledgecenter.zuora.com/DC_Developers/BA_Data_Query/BA_SQL_Queries_in_Data_Query) for more information.\n',
      }),
    readDeleted: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Indicates whether the query will retrieve only the deleted record. If `readDeleted` is set to `false` or it is not included in the request body, the query will retrieve only the non-deleted records. If it is set to `true`, only the deleted records will be retrieved.\n\nNote that Data Query is subject to Zuora Data Retention Policy. The retention period of deleted data is 30 days. You can only retrieve deleted data for 30 days through Data Query.\n',
      }),
    sourceData: z
      .enum(['DATAHUB', 'LIVE'])
      .exactOptional()
      .openapi({
        description:
          'Specifiy that data queries run against the live transactional databases at Zuora (Data Query Live), or run against the optimized, replicated database at 12 hours freshness for high volume extraction (Data Query Unlimited).\n\n**Note**: Data Query Unlimited is an Early Adopter feature.  If you want to have access to the feature, submit a request at [Zuora Global Support](http://support.zuora.com/). \n\n* `DATAHUB` - Data queries run against the optimized, replicated database at 12 hours freshness for high volume extraction (Data Query Unlimited). Data Query Unlimited is an Early Adopter feature.  If you want to have access to the feature, submit a request at [Zuora Global Support](http://support.zuora.com/). \n* `LIVE` - Data queries run against the live transactional databases at Zuora (Data Query Live).\n\nThe default value is `LIVE`.\n',
      }),
    useIndexJoin: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Indicates whether to use Index Join. Index join is useful when you have a specific reference value in your WHERE clause to index another large table by. See [Use Index Join](https://knowledgecenter.zuora.com/DC_Developers/BA_Data_Query/Best_practices_of_Data_Query#Use_Index_Join) for more information.',
      }),
  })
  .openapi({
    example: {
      compression: 'NONE',
      output: { target: 'S3' },
      outputFormat: 'JSON',
      query: 'SELECT accountnumber, balance FROM Account WHERE Account.balance > 100',
    },
    required: ['query', 'outputFormat', 'compression', 'output'],
  })
  .openapi('SubmitDataQueryRequest')

